/* Track checklist state is stored on the album, scoped to the selected catalog edition. */
(function(root){
 const key=m=>JSON.stringify([m.facts?.Disc||'1',m.facts?.['Track number']||'',m.id]);
 function update(previous,edition,rows,selected,done,more){const next=structuredClone(previous||{editions:{}});const old=next.editions[edition]||{completed:[]};const checked=new Set(old.completed);selected.forEach(id=>done?checked.add(id):checked.delete(id));const ids=more?[...new Set([...(old.ids||[]),...rows.map(key)])]:rows.map(key);next.editions[edition]={ids,completed:[...checked],total:more?(old.total||null):ids.length};next.active=edition;return next;}
 function progress(state,edition){const row=state?.editions?.[edition];return {completed:row?new Set(row.completed.filter(id=>row.ids.includes(id))).size:0,total:row?.total||null};}
 if(typeof module==='object')module.exports={key,update,progress};if(typeof document==='undefined')return;
 function bind(section,media,album,rows,more){section.querySelector('.album-progress-summary')?.remove();const edition=album.source.provider+':'+album.source.id;
  const entry=()=>items.find(x=>x.metadata?.kind==='album'&&FolioIdentity.same(x.metadata,media));
  const panel=document.createElement('div');panel.className='series-progress-summary album-progress-summary';section.querySelector('.album-track-list').before(panel);
  section.querySelectorAll('.track-completion').forEach(el=>el.remove());section.querySelectorAll('.album-track-row').forEach((row,i)=>{const label=document.createElement('label');label.className='track-completion';label.innerHTML=`<input type="checkbox" aria-label="Completed song: ${esc(rows[i].title)}">`;row.prepend(label);label.querySelector('input').onchange=e=>save([key(rows[i])],e.target.checked);});
  function draw(){const x=entry(),p=progress(x?.albumProgress,edition),checked=new Set(x?.albumProgress?.editions?.[edition]?.completed||[]);panel.innerHTML=x?`<strong>${p.completed}${p.total?' / '+p.total:''} tracks completed</strong><p>${more?'Load all tracks to calculate the album total.':'Song checkmarks update album progress automatically.'} Progress is saved for this catalog edition.</p>${p.total?`<progress value="${p.completed}" max="${p.total}" aria-label="Album track progress"></progress>`:''}<button type="button" data-complete-album ${more||!rows.length?'disabled':''}>${p.total&&p.completed===p.total?'Undo album completion':'Mark album complete'}</button>${x.albumProgress?'<button type="button" data-manual-album>Use manual progress</button>':''}`:'Add the album to your library to save song completion. Individual songs do not need to be added.';
   section.querySelectorAll('.track-completion input').forEach((el,i)=>{el.checked=checked.has(key(rows[i]));el.disabled=!x;});panel.querySelector('[data-complete-album]')?.addEventListener('click',()=>save(rows.map(key),!(p.total&&p.completed===p.total)));panel.querySelector('[data-manual-album]')?.addEventListener('click',()=>{const old=x.albumProgress;delete x.albumProgress;if(!persist())x.albumProgress=old;draw();});
   const dialog=section.closest('dialog');if(x&&dialog?.id==='detail'){for(const [selector,value] of [['#episodes-done',x.episodeProgress?.completed||0],['#episodes-total',x.episodeProgress?.total||''],['#progress-unit','Tracks']]){const el=dialog.querySelector(selector);if(el){if(x.albumProgress)el.value=value;el.disabled=!!x.albumProgress;}}const button=dialog.querySelector('#episode-form button[type=submit]');if(button)button.disabled=!!x.albumProgress;const bar=dialog.querySelector('.activity-section progress');if(bar&&x.episodeProgress?.total){bar.max=x.episodeProgress.total;bar.value=x.episodeProgress.completed;}const text=dialog.querySelector('.activity-section progress + .muted');if(text&&x.albumProgress)text.textContent=`${x.episodeProgress.completed} of ${x.episodeProgress.total||'unknown'} completed`;const note=dialog.querySelector('#episode-form .disclaimer');if(note)note.textContent=x.albumProgress?'Song checkmarks control album progress. Choose Use manual progress above to edit the count directly.':'Set overall progress manually, or use song checkmarks above.';}
  }
  function save(selected,done){try{const latest=JSON.parse(localStorage.getItem('folio-library-v1')||'null');if(Array.isArray(latest))items=root.FolioLibraryPatch?root.FolioLibraryPatch.entries(latest):latest;}catch{}const x=entry();if(!x)return;const before=structuredClone(x);if(!x.albumProgress&&x.episodeProgress?.completed&&!confirm('Use song checkmarks instead of the manual count? Your previous count will be retained.')){draw();return;}if(!x.albumProgress)x.previousManualTrackProgress=structuredClone(x.episodeProgress||{});x.albumProgress=update(x.albumProgress,edition,rows,selected,done,more);x.episodeProgress=progress(x.albumProgress,edition);x.progressUnit='Tracks';const p=x.episodeProgress;if(p.total&&p.completed===p.total)x.status='Completed';else if(p.completed||x.status==='Completed')x.status='In progress';delete x.completionPreviousStatus;if(!persist()){Object.keys(x).forEach(k=>delete x[k]);Object.assign(x,before);draw();return;}render();draw();section.closest('dialog').querySelectorAll('[data-status-id]').forEach(el=>{if(el.dataset.statusId===x.id)el.value=x.status;});toast(`${p.completed}${p.total?' / '+p.total:''} tracks completed`);}
  function onSave(){if(!section.isConnected||!panel.isConnected){document.removeEventListener('submit',onSave);return;}queueMicrotask(draw);}document.addEventListener('submit',onSave);draw();
 }
 root.FolioAlbumProgress={bind};
})(globalThis);
